    // -- Concurrency tests --

    #[test]
    fn concurrent_spend_different_utxos() {
        let h = TestHarness::new(100, TxFlags::empty());
        let engine = h.engine.clone();
        let key = h.key;

        let handles: Vec<_> = (0..100u32)
            .map(|i| {
                let engine = engine.clone();
                let mut hash = [0u8; 32];
                hash[0] = (i & 0xFF) as u8;
                hash[1] = ((i >> 8) & 0xFF) as u8;
                let mut sd = [0u8; 36];
                sd[0] = i as u8;
                sd[32..36].copy_from_slice(&1u32.to_le_bytes());

                std::thread::spawn(move || {
                    let req = SpendRequest {
                        tx_key: key,
                        offset: i,
                        utxo_hash: hash,
                        spending_data: sd,
                        ignore_conflicting: false,
                        ignore_locked: false,
                        current_block_height: 1000,
                        block_height_retention: 288,
                    };
                    engine.spend(&req).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!({ meta.spent_utxos }, 100);
    }

    #[test]
    fn concurrent_spend_same_utxo_same_data() {
        let h = TestHarness::new(10, TxFlags::empty());
        let engine = h.engine.clone();
        let key = h.key;
        let hash = h.slot_hash(5);
        let sd = h.make_spending_data(0xAB);

        let handles: Vec<_> = (0..100)
            .map(|_| {
                let engine = engine.clone();
                std::thread::spawn(move || {
                    let req = SpendRequest {
                        tx_key: key,
                        offset: 5,
                        utxo_hash: hash,
                        spending_data: sd,
                        ignore_conflicting: false,
                        ignore_locked: false,
                        current_block_height: 1000,
                        block_height_retention: 288,
                    };
                    engine.spend(&req).unwrap(); // All should succeed (idempotent)
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!({ meta.spent_utxos }, 1); // Only incremented once
        let slot = engine.read_slot(&key, 5).unwrap();
        assert_eq!(slot.spending_data, sd);
    }

    #[test]
    fn concurrent_spend_same_utxo_different_data() {
        let h = TestHarness::new(10, TxFlags::empty());
        let engine = h.engine.clone();
        let key = h.key;
        let hash = h.slot_hash(5);

        let results: Vec<_> = (0..100u8)
            .map(|i| {
                let engine = engine.clone();
                std::thread::spawn(move || {
                    let mut sd = [0u8; 36];
                    sd[0] = i;
                    sd[32..36].copy_from_slice(&1u32.to_le_bytes());
                    let req = SpendRequest {
                        tx_key: key,
                        offset: 5,
                        utxo_hash: hash,
                        spending_data: sd,
                        ignore_conflicting: false,
                        ignore_locked: false,
                        current_block_height: 1000,
                        block_height_retention: 288,
                    };
                    engine.spend(&req)
                })
            })
            .collect();

        let mut successes = 0;
        let mut already_spent = 0;
        let mut already_spent_payloads = Vec::new();
        for handle in results {
            match handle.join().unwrap() {
                Ok(_) => successes += 1,
                Err(SpendError::AlreadySpent { spending_data, .. }) => {
                    already_spent += 1;
                    already_spent_payloads.push(spending_data);
                }
                other => panic!("unexpected result: {other:?}"),
            }
        }

        assert_eq!(successes, 1);
        assert_eq!(already_spent, 99);

        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!({ meta.spent_utxos }, 1);
        let winning_spending_data = engine.read_slot(&key, 5).unwrap().spending_data;
        assert!(
            already_spent_payloads
                .iter()
                .all(|payload| *payload == winning_spending_data),
            "every AlreadySpent error must return the winning spending_data"
        );
    }

    /// Increment 4b-1: the engine caches per-store log-structured-ness from the
    /// allocator so the spend path can branch (relocate vs in-place) without
    /// locking the allocator on the hot path.
    #[test]
    fn store_log_structured_reflects_the_allocator_engine() {
        // Segment allocator → log-structured store.
        let seg_dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        let seg = crate::segment_allocator::SegmentAllocator::new(seg_dev.clone(), 8 * 1024 * 1024)
            .unwrap();
        let seg_engine = Engine::new(
            seg_dev,
            Index::new(64).unwrap(),
            seg,
            StripedLocks::new(64),
            DahIndex::new(),
        );
        assert!(seg_engine.store_is_log_structured(0));

        // In-place (SlotAllocator) → NOT log-structured.
        let slot_dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(16 * 1024 * 1024, 4096).unwrap());
        let slot = SlotAllocator::new(slot_dev.clone()).unwrap();
        let slot_engine = Engine::new(
            slot_dev,
            Index::new(64).unwrap(),
            slot,
            StripedLocks::new(64),
            DahIndex::new(),
        );
        assert!(!slot_engine.store_is_log_structured(0));
    }

    // ---- Increment 4b-2: the `relocate_record` primitive (segment engine) ----

    /// Build a segment-engine `Engine` with one seeded 4-UTXO record (all
    /// unspent), returning `(engine, device, key, metadata, slots, old_offset)`.
    fn seg_engine_with_record() -> (
        Arc<Engine>,
        Arc<dyn BlockDevice>,
        TxKey,
        TxMetadata,
        Vec<UtxoSlot>,
        u64,
    ) {
        let dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        let seg =
            crate::segment_allocator::SegmentAllocator::new(dev.clone(), 8 * 1024 * 1024).unwrap();
        let engine = Arc::new(Engine::new(
            dev.clone(),
            Index::new(64).unwrap(),
            seg,
            StripedLocks::new(64),
            DahIndex::new(),
        ));
        assert!(engine.store_is_log_structured(0));

        let utxo_count = 4u32;
        let mut txid = [0u8; 32];
        txid[0] = 0xAB;
        let key = TxKey { txid };

        let record_size = TxMetadata::record_size_for(utxo_count);
        let offset = engine
            .allocator_for(0)
            .lock()
            .allocate(record_size)
            .unwrap();

        let mut meta = TxMetadata::new(utxo_count);
        meta.tx_id = txid;
        let slots: Vec<UtxoSlot> = (0..utxo_count)
            .map(|i| {
                let mut h = [0u8; 32];
                h[0] = (i as u8) + 1;
                UtxoSlot::new_unspent(h)
            })
            .collect();
        io::write_full_record(&*dev, offset, &meta, &slots).unwrap();

        engine
            .register(
                key,
                TxIndexEntry {
                    device_id: 0,
                    record_offset: offset,
                    mined_slot: crate::index::mined_index::NO_MINED_SLOT,
                },
            )
            .unwrap();

        (engine, dev, key, meta, slots, offset)
    }

    /// F-G2-001: `read_metadata_for_key` must tell a benign delete/relocate
    /// race (record gone under a lock-free-captured offset) apart from genuine
    /// on-device corruption. When the CRC-checked fast read fails, it
    /// re-resolves the key through the primary index:
    ///   - still mapped to THIS (device, offset) → surface the StorageError
    ///     (real corruption worth reporting);
    ///   - moved or unmapped                      → return TxNotFound (the
    ///     post-delete answer; the unregister→tombstone ordering guarantees the
    ///     re-lookup observes the removal whenever the zeroed header is visible).
    #[test]
    fn read_metadata_for_key_distinguishes_race_from_corruption() {
        let (engine, dev, key, _meta, _slots, offset) = seg_engine_with_record();

        // Corrupt the on-device metadata header: overwrite it with raw zeros so
        // the stored CRC (0x0000_0000) no longer matches the computed CRC and
        // the lock-free read fails — the exact shape a just-tombstoned/torn
        // header presents to a reader that captured the offset pre-unregister.
        let align = dev.alignment();
        let zbuf = AlignedBuf::new(io::align_up(METADATA_SIZE, align), align);
        dev.pwrite_all_at(&zbuf, offset).unwrap();

        // Sanity: the raw fast read now errors on the zeroed header.
        let raw = engine.read_metadata_fast(0, offset);
        assert!(
            matches!(raw, Err(SpendError::StorageError { .. })),
            "zeroed header must fail the CRC-checked fast read, got {raw:?}"
        );

        // Case A — key STILL maps to this (device, offset): genuine corruption,
        // surface the storage error rather than masking it as a missing tx.
        let still_here = engine.read_metadata_for_key(0, &key, offset);
        assert!(
            matches!(still_here, Err(SpendError::StorageError { .. })),
            "current mapping → corruption must surface as StorageError, got {still_here:?}"
        );

        // Case B — the delete unregistered the key first (unregister→tombstone
        // ordering): the re-lookup observes the removal and the same failed read
        // now resolves to TxNotFound, the post-delete answer the caller expects.
        engine.index.unregister(&key);
        let gone = engine.read_metadata_for_key(0, &key, offset);
        assert!(
            matches!(gone, Err(SpendError::TxNotFound)),
            "unmapped key → benign race must resolve to TxNotFound, got {gone:?}"
        );
    }

    /// F-X-007 (BC-02) regression: the cache-path `write_zeroed_metadata_header`
    /// (delete's tombstone) must hold the per-block write guard across its RMW.
    /// Before the fix it did a bare pread+patch+pwrite with NO lock, so for a
    /// packed record it wrote the WHOLE covering block back and clobbered a
    /// block-neighbour packed record a concurrent writer had just written
    /// (all-zero neighbour → `CRC mismatch: expected 0x00000000` on a later
    /// setMined/delete read; observed on the segment engine under load).
    ///
    /// A cache-backed device (`as_raw_ptr == None`) forces the cache branch. The
    /// test holds the block's write guard and asserts the tombstone BLOCKS on it
    /// (it completes only once the guard is released) — proving the RMW is now
    /// serialized against every other writer of the shared block.
    #[test]
    fn tombstone_cache_path_holds_block_write_guard() {
        use std::sync::atomic::{AtomicBool, Ordering};
        let mem: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        let dev: Arc<dyn BlockDevice> = Arc::new(crate::cache::CachingDevice::new(
            mem,
            64 * 1024 * 1024,
            true,
            3_600_000,
        ));
        let seg =
            crate::segment_allocator::SegmentAllocator::new(dev.clone(), 8 * 1024 * 1024).unwrap();
        let engine = Arc::new(Engine::new(
            dev.clone(),
            Index::new(64).unwrap(),
            seg,
            StripedLocks::new(64),
            DahIndex::new(),
        ));
        // The whole point: the cache device exposes no raw pointer, so the
        // tombstone takes the (previously unlocked) cache branch.
        assert!(engine.device_ptr_for(0).is_null());

        let utxo_count = 4u32;
        let record_size = TxMetadata::record_size_for(utxo_count);
        let offset = engine
            .allocator_for(0)
            .lock()
            .allocate(record_size)
            .unwrap();
        let mut meta = TxMetadata::new(utxo_count);
        meta.tx_id = [0x5A; 32];
        let slots: Vec<UtxoSlot> = (0..utxo_count)
            .map(|_| UtxoSlot::new_unspent([0u8; 32]))
            .collect();
        io::write_full_record(&*dev, offset, &meta, &slots).unwrap();

        // Hold the per-block write guard the fixed tombstone must acquire.
        let guards = io::lock_span_blocks(offset, METADATA_SIZE as u64);

        let done = Arc::new(AtomicBool::new(false));
        let e2 = engine.clone();
        let d2 = done.clone();
        let h = std::thread::spawn(move || {
            e2.write_zeroed_metadata_header(0, offset, record_size)
                .unwrap();
            d2.store(true, Ordering::SeqCst);
        });
        // While the guard is held the tombstone cannot make progress.
        std::thread::sleep(std::time::Duration::from_millis(100));
        assert!(
            !done.load(Ordering::SeqCst),
            "tombstone must block on the per-block write guard (unlocked = clobbers neighbours)"
        );
        drop(guards);
        h.join().unwrap();
        assert!(
            done.load(Ordering::SeqCst),
            "tombstone completes once the block write guard is released"
        );
    }

    #[test]
    fn relocate_record_moves_record_verbatim() {
        let (engine, dev, key, meta, slots, old_offset) = seg_engine_with_record();

        // Give the entry a non-sentinel mined_slot before relocating: every
        // other relocate test registers `NO_MINED_SLOT`, so a regression that
        // reset the pointer on relocate would produce byte-identical output
        // there. This proves `relocate_record` carries the pre-relocate
        // `mined_slot` forward rather than resetting it.
        engine
            .register(
                key,
                TxIndexEntry {
                    device_id: 0,
                    record_offset: old_offset,
                    mined_slot: 777,
                },
            )
            .unwrap();

        // Pure move: no baked-in mutation.
        let new_offset = engine.relocate_record(0, &key, &meta, &[]).unwrap();
        assert_ne!(
            new_offset, old_offset,
            "append-cursor must hand out a fresh offset"
        );

        // Index now points at the new offset.
        let entry = engine
            .lookup(&key)
            .expect("key still indexed after relocate");
        assert_eq!(entry.record_offset, new_offset);
        assert_eq!(
            entry.mined_slot, 777,
            "relocate must carry the pre-relocate mined_slot forward"
        );
        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!({ meta.utxo_count }, 4);

        // The relocated image is byte-faithful: metadata identity + every slot.
        let m2 = io::read_metadata(&*dev, new_offset).unwrap();
        assert_eq!({ m2.tx_id }, key.txid);
        assert_eq!({ m2.utxo_count }, 4);
        let s2 = io::read_all_utxo_slots(&*dev, new_offset, 4).unwrap();
        for (i, orig) in slots.iter().enumerate() {
            assert_eq!(s2[i].hash, orig.hash, "slot {i} hash preserved");
            assert_eq!(s2[i].status, UTXO_UNSPENT, "slot {i} status preserved");
        }

        // The old extent is dead-marked but its bytes stay intact (append-only
        // never overwrites until defrag), so a lock-free reader that still holds
        // the old offset reads a valid record rather than garbage.
        let m_old = io::read_metadata(&*dev, old_offset).unwrap();
        assert_eq!({ m_old.tx_id }, key.txid);
    }

    #[test]
    fn relocate_record_bakes_in_slot_and_metadata_mutation() {
        let (engine, dev, key, meta, slots, _old) = seg_engine_with_record();

        // Mutate metadata (spend bookkeeping) + flip slot 1 to SPENT — the exact
        // shape the segment spend path will hand the primitive in 4c.
        let mut new_meta = meta;
        new_meta.spent_utxos = 1;
        new_meta.generation = 7;
        let spending_data = [0x42u8; 36];
        let spent_slot = UtxoSlot::new_spent(slots[1].hash, spending_data);

        let new_offset = engine
            .relocate_record(0, &key, &new_meta, &[(1, spent_slot)])
            .unwrap();

        // Baked-in metadata landed.
        let m = io::read_metadata(&*dev, new_offset).unwrap();
        assert_eq!({ m.spent_utxos }, 1);
        assert_eq!({ m.generation }, 7);

        // Slot 1 is SPENT with the new spending data; the others are untouched.
        let s = io::read_all_utxo_slots(&*dev, new_offset, 4).unwrap();
        assert_eq!(s[1].status, UTXO_SPENT);
        assert_eq!(s[1].spending_data, spending_data);
        assert_eq!(s[1].hash, slots[1].hash);
        assert_eq!(s[0].status, UTXO_UNSPENT);
        assert_eq!(s[2].status, UTXO_UNSPENT);
        assert_eq!(s[3].status, UTXO_UNSPENT);

        // The index cached fields are rebuilt from the new metadata — identical to
        // what `replay_relocate` reconstructs from the device (live == recovered).
        let entry = engine.lookup(&key).unwrap();
        assert_eq!(entry.record_offset, new_offset);
        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!({ meta.spent_utxos }, 1);
        assert_eq!({ meta.generation }, 7);
    }

    #[test]
    fn relocate_record_journals_nothing_for_segment() {
        use crate::redo::{RedoLog, RedoOp};

        // P0 double-spend fix: `relocate_record` journals NO relocate redo for the
        // segment engine (STANDALONE included, not just clustered). The spend's
        // self-sufficient SpendV2 (emitted by the caller) is the authoritative spend
        // redo, and defrag relocates are checkpoint-covered + revert-safe. A thin
        // `Relocate` would re-point recovery to the still-buffered new offset and
        // could revert an acked spend on a power-loss before the checkpoint.
        let (engine, _dev, key, meta, _slots, old) = seg_engine_with_record();

        let log_dev: Arc<dyn BlockDevice> = Arc::new(MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let log = RedoLog::open(log_dev.clone(), 0, 1024 * 1024).unwrap();
        engine.set_redo_log(Arc::new(parking_lot::Mutex::new(log)));

        // The relocate still MOVES the record on the device and re-points the index.
        let new_offset = engine.relocate_record(0, &key, &meta, &[]).unwrap();
        assert_ne!(new_offset, old, "the record physically moved");
        assert_eq!(engine.lookup(&key).unwrap().record_offset, new_offset);

        // Buffered append: flush so a fresh reopen would surface any journaled entry.
        engine.redo_log().unwrap().lock().flush().unwrap();

        let log2 = RedoLog::open(log_dev, 0, 1024 * 1024).unwrap();
        let entries = log2.recover().unwrap();
        assert!(
            !entries
                .iter()
                .any(|e| matches!(&e.op, RedoOp::Relocate { tx_key, .. } if *tx_key == key)),
            "segment relocate must journal NO Relocate redo (SpendV2 / checkpoint cover it)"
        );
    }

    #[test]
    fn segment_relocate_with_spend_mutation_journals_nothing() {
        use crate::redo::{RedoLog, RedoOp};

        let (engine, dev, key, meta, slots, _old) = seg_engine_with_record();

        // A segment relocate that bakes in a spend mutation must journal NOTHING
        // itself — the spend's convertible per-vout SpendV2 (emitted by the dispatch
        // / replica caller) is the authoritative redo, so `relocate_record` writes no
        // relocate redo at all. This is the unified model (standalone == clustered).
        let log_dev: Arc<dyn BlockDevice> = Arc::new(MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let log = RedoLog::open(log_dev.clone(), 0, 1024 * 1024).unwrap();
        engine.set_redo_logs(vec![Arc::new(parking_lot::Mutex::new(log))]);

        let mut new_meta = meta;
        new_meta.spent_utxos = 1;
        new_meta.generation = 9;
        let spending_data = [0x37u8; 36];
        let spent_slot = UtxoSlot::new_spent(slots[1].hash, spending_data);

        let new_offset = engine
            .relocate_record(0, &key, &new_meta, &[(1, spent_slot)])
            .unwrap();

        // The relocate still MOVES the record + bakes in the spend on the device.
        let s = io::read_all_utxo_slots(&*dev, new_offset, 4).unwrap();
        assert_eq!(s[1].status, UTXO_SPENT);
        assert_eq!(s[1].spending_data, spending_data);
        let entry = engine.lookup(&key).unwrap();
        assert_eq!(entry.record_offset, new_offset);
        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!({ meta.generation }, 9);

        // But it journaled NOTHING for this key — no relocate redo at all.
        engine.flush_all_redo().unwrap();
        let log2 = RedoLog::open(log_dev, 0, 1024 * 1024).unwrap();
        let entries = log2.recover().unwrap();
        assert!(
            !entries.iter().any(|e| matches!(
                &e.op,
                RedoOp::Relocate { tx_key, .. } if *tx_key == key
            )),
            "segment relocate must journal no relocate redo — SpendV2 is the redo"
        );
    }

    #[test]
    fn engine_spend_relocates_on_segment_store() {
        // Phase 2: the single-spend entry point (used in production only by the
        // replica apply path) must RELOCATE on a log-structured store, not RMW in
        // place — so a replica physically mirrors the master.
        let (engine, dev, key, _meta, slots, old_offset) = seg_engine_with_record();

        let req = SpendRequest {
            tx_key: key,
            offset: 2,
            utxo_hash: slots[2].hash,
            spending_data: [0x11u8; 36],
            ignore_conflicting: true,
            ignore_locked: true,
            current_block_height: 100,
            block_height_retention: 0,
        };
        engine.spend(&req).unwrap();

        // The record MOVED to a fresh append-cursor offset.
        let entry = engine.lookup(&key).unwrap();
        assert_ne!(
            entry.record_offset, old_offset,
            "segment spend must relocate, not RMW in place"
        );

        // Logical state at the new offset is correct: slot 2 SPENT with the
        // spending data, counter + generation bumped.
        let s = io::read_all_utxo_slots(&*dev, entry.record_offset, 4).unwrap();
        assert_eq!(s[2].status, UTXO_SPENT);
        assert_eq!(s[2].spending_data, [0x11u8; 36]);
        assert_eq!(s[0].status, UTXO_UNSPENT);
        let m = io::read_metadata(&*dev, entry.record_offset).unwrap();
        assert_eq!({ m.spent_utxos }, 1);
        let meta = engine.read_metadata(&key).unwrap();
        assert_eq!(
            { meta.spent_utxos },
            1,
            "index re-pointed to the new record"
        );

        // A second, different-vout spend relocates AGAIN and accumulates.
        let req2 = SpendRequest {
            tx_key: key,
            offset: 0,
            utxo_hash: slots[0].hash,
            spending_data: [0x22u8; 36],
            ignore_conflicting: true,
            ignore_locked: true,
            current_block_height: 100,
            block_height_retention: 0,
        };
        engine.spend(&req2).unwrap();
        let entry2 = engine.lookup(&key).unwrap();
        assert_ne!(entry2.record_offset, entry.record_offset, "relocates again");
        let m2 = io::read_metadata(&*dev, entry2.record_offset).unwrap();
        assert_eq!({ m2.spent_utxos }, 2);
    }

    // (Removed `standalone_relocate_still_journals_thin_relocate`: the STANDALONE
    // vs CLUSTERED gating of the thin `Relocate` no longer exists — both journal
    // nothing now. The primitive contract is covered by
    // `relocate_record_journals_nothing_for_segment` (standalone) and
    // `clustered_relocate_journals_nothing_spendv2_is_the_redo` (clustered), and the
    // end-to-end spend recovery by
    // `server::dispatch::tests::standalone_segment_spend_recoverable_from_redo_alone_after_powerloss`.)

    /// P0 (redo header-clobber → acked data loss): a checkpoint's fence/reclaim
    /// header write must NOT be reverted by an in-flight group-commit flush whose
    /// Phase-2 header pwrite was snapshotted BEFORE the fence advanced.
    ///
    /// Both the flush's Phase-2 (`RedoLog::commit_flush`) and the checkpoint's
    /// fence/reclaim rewrite the SAME single redo header block, which carries no
    /// generation/epoch — the last pwrite wins. A group-commit flush RELEASES the
    /// log lock before its slow O_DIRECT header pwrite, so the checkpoint (holding
    /// only the log lock) can advance `checkpoint_seq`/`oldest_seg` and write the
    /// new header in between — and then the flush's STALE snapshotted header lands
    /// LAST, reverting the fence. On the next crash, ring recovery scans from the
    /// reverted (already-reclaimed) `oldest_seg` and drops durably-acked entries.
    ///
    /// Deterministic reproduction: a device parks the FIRST header pwrite (offset
    /// == `log_offset`) once armed. A background `flush_all_redo` parks there
    /// holding the committer's `flush_guard` with the log lock already released
    /// (Phase-2). The checkpoint's `mark_recovery_progress_all` +
    /// `compact_all_redo_through` then run. Pre-fix the checkpoint takes only the
    /// log lock (free), writes the advanced header, and is clobbered when the
    /// parked stale header is released → the durable fence regresses to 0.
    /// Post-fix the checkpoint blocks on `flush_guard` until the flush fully
    /// completes, so its advanced header is written LAST and survives.
    #[test]
    fn checkpoint_fence_survives_inflight_flush_header_pwrite() {
        use crate::redo::{RedoLog, RedoOp};
        use std::sync::atomic::AtomicU32;
        use std::time::Duration;

        /// Parks the FIRST pwrite targeting the header block once armed; every
        /// other write/read/sync passes through. Counts header writes that
        /// actually landed so the driver never has to guess from a wall clock.
        struct HeaderParkDev {
            inner: MemoryDevice,
            header_offset: u64,
            armed: AtomicBool,        // false during setup so the fill flush passes
            parked_once: AtomicBool,  // only the FIRST armed header write parks
            in_park: AtomicBool,      // true while the flush's header write is parked
            release: AtomicBool,      // set true to let the parked write land
            header_writes: AtomicU32, // header writes that actually LANDED
        }
        impl BlockDevice for HeaderParkDev {
            fn pread(&self, b: &mut [u8], o: u64) -> crate::device::Result<usize> {
                self.inner.pread(b, o)
            }
            fn pwrite(&self, b: &[u8], o: u64) -> crate::device::Result<usize> {
                if o == self.header_offset
                    && self.armed.load(Ordering::SeqCst)
                    && !self.parked_once.swap(true, Ordering::SeqCst)
                {
                    self.in_park.store(true, Ordering::SeqCst);
                    while !self.release.load(Ordering::SeqCst) {
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    self.in_park.store(false, Ordering::SeqCst);
                }
                let n = self.inner.pwrite(b, o)?;
                if o == self.header_offset {
                    self.header_writes.fetch_add(1, Ordering::SeqCst);
                }
                Ok(n)
            }
            fn alignment(&self) -> usize {
                self.inner.alignment()
            }
            fn size(&self) -> u64 {
                self.inner.size()
            }
            fn sync(&self) -> crate::device::Result<()> {
                self.inner.sync()
            }
            fn sync_data(&self) -> crate::device::Result<()> {
                self.inner.sync_data()
            }
        }

        let segment_size = 4096u64;
        let count = 4u64;
        let total = 4096 + segment_size * count;
        let dev = Arc::new(HeaderParkDev {
            inner: MemoryDevice::new(total, 4096).unwrap(),
            header_offset: 0,
            armed: AtomicBool::new(false),
            parked_once: AtomicBool::new(false),
            in_park: AtomicBool::new(false),
            release: AtomicBool::new(false),
            header_writes: AtomicU32::new(0),
        });
        let ring_dev: Arc<dyn BlockDevice> = dev.clone();
        let log = Arc::new(parking_lot::Mutex::new(
            RedoLog::format_ring(ring_dev.clone(), 0, total, segment_size).unwrap(),
        ));

        // Minimal engine — only the redo path is exercised here.
        let data: Arc<dyn BlockDevice> = Arc::new(MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let alloc = SlotAllocator::new(data.clone()).unwrap();
        let index = Index::new(128).unwrap();
        let engine = Arc::new(Engine::new(
            data,
            index,
            alloc,
            StripedLocks::new(64),
            DahIndex::new(),
        ));
        engine.set_redo_logs(vec![log.clone()]);
        engine.set_buffered_durability(true);

        let freeze = |n: u8| RedoOp::Freeze {
            tx_key: crate::index::TxKey { txid: [n; 32] },
            offset: 0,
        };

        // Fill several segments and flush durably (NOT armed → passes). The fence
        // below covers all of these, so reclaim must free the older segments.
        {
            let mut l = log.lock();
            for i in 0..200u32 {
                l.append(freeze((i % 251) as u8)).unwrap();
            }
            l.flush().unwrap();
            assert!(l.is_segment_ring(), "ring layout");
        }
        let fence = log.lock().current_sequence().saturating_sub(1);
        assert!(fence > 0, "fence must be a real sequence: {fence}");

        // One MORE buffered append: this is what the in-flight flush carries, and
        // its stale header snapshot (checkpoint_seq 0, oldest_seg 0) is the clobber.
        log.lock().append(freeze(0xAB)).unwrap();

        // Arm: the next header pwrite (the flush's Phase-2) parks.
        dev.armed.store(true, Ordering::SeqCst);

        // T1: background flush parks at its header pwrite holding the committer's
        // flush_guard, log lock already released (Phase-2).
        let eng1 = engine.clone();
        let t1 = std::thread::spawn(move || eng1.flush_all_redo());
        let mut waited = 0;
        while !dev.in_park.load(Ordering::SeqCst) {
            std::thread::sleep(Duration::from_millis(1));
            waited += 1;
            assert!(waited < 5000, "flush never reached its header pwrite");
        }

        // T2: the checkpoint fence + reclaim (the production per-store path).
        let eng2 = engine.clone();
        let done = Arc::new(AtomicBool::new(false));
        let done2 = done.clone();
        let t2 = std::thread::spawn(move || {
            eng2.mark_recovery_progress_all(fence).unwrap();
            eng2.compact_all_redo_through(fence).unwrap();
            done2.store(true, Ordering::SeqCst);
        });

        // Wait until EITHER the checkpoint finished (pre-fix: not blocked, lands its
        // header while the flush is parked) OR a bounded timeout (post-fix: blocked
        // on flush_guard). The RESULT asserted below is deterministic either way —
        // this only sequences the pre-fix clobber before release.
        let mut w = 0;
        while !done.load(Ordering::SeqCst) && w < 400 {
            std::thread::sleep(Duration::from_millis(1));
            w += 1;
        }

        // Release the parked stale header pwrite. Pre-fix it lands LAST, clobbering
        // the checkpoint's header; post-fix the (blocked) checkpoint runs after the
        // flush and writes the advanced header LAST.
        dev.release.store(true, Ordering::SeqCst);
        t1.join().unwrap().expect("flush ok");
        t2.join().unwrap();

        // Read the DURABLE header via a fresh reopen and assert the fence did NOT
        // regress: recovery must see the checkpoint's advanced fence, and only the
        // single post-fence entry remains to replay.
        dev.armed.store(false, Ordering::SeqCst); // no parking during reopen
        let reopened = RedoLog::open(ring_dev, 0, total).unwrap();
        let (entries, durable_fence) = reopened.recover_with_fence().unwrap();
        assert_eq!(
            durable_fence, fence,
            "durable checkpoint fence regressed: a stale in-flight flush header \
             clobbered the checkpoint's advance (got {durable_fence}, want {fence})"
        );
        assert_eq!(
            entries.len(),
            1,
            "only the single post-fence entry should replay; a regressed fence \
             replays the whole reclaimed prefix (got {} entries)",
            entries.len()
        );
    }

    #[test]
    fn relocate_record_rejects_out_of_range_vout() {
        let (engine, _dev, key, meta, slots, _old) = seg_engine_with_record();

        // vout 4 is out of range for a 4-UTXO record (valid: 0..=3).
        let err = engine
            .relocate_record(0, &key, &meta, &[(4, slots[0])])
            .unwrap_err();
        match err {
            SpendError::StorageError { detail } => {
                assert!(detail.contains("vout 4"), "got: {detail}");
            }
            other => panic!("expected StorageError, got {other:?}"),
        }
    }

    /// Increment 5c: the checkpoint's defrag fast path reclaims a drained segment
    /// through the engine, bounding growth. Drains a segment via the allocator,
    /// then `defrag_reclaim_fully_dead` (what the checkpoint calls) reclaims it.
    #[test]
    fn defrag_reclaim_fully_dead_reclaims_a_drained_segment() {
        let dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        // 2-block segments so a single segment drains quickly.
        let seg = crate::segment_allocator::SegmentAllocator::new(dev.clone(), 2 * 4096).unwrap();
        let engine = Engine::new(
            dev,
            Index::new(64).unwrap(),
            seg,
            StripedLocks::new(64),
            DahIndex::new(),
        );
        // Fill seg0, advance into seg1, then dead-mark all of seg0.
        {
            let alloc = engine.allocator_for(0);
            let mut a = alloc.lock();
            let o0 = a.allocate(4096).unwrap();
            let o1 = a.allocate(4096).unwrap(); // seg0 full
            let _ = a.allocate(4096).unwrap(); // seg1 open
            a.free(o0, 4096).unwrap();
            a.free(o1, 4096).unwrap(); // seg0 fully dead
        }
        assert_eq!(
            engine.defrag_reclaim_fully_dead(),
            1,
            "the drained seg0 must be reclaimed"
        );
        // Idempotent: nothing left to reclaim.
        assert_eq!(engine.defrag_reclaim_fully_dead(), 0);
    }

    #[test]
    fn defrag_reclaim_and_compact_are_noop_while_lifecycle_pinned() {
        let dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        let seg = crate::segment_allocator::SegmentAllocator::new(dev.clone(), 2 * 4096).unwrap();
        let engine = Engine::new(
            dev,
            Index::new(64).unwrap(),
            seg,
            StripedLocks::new(64),
            DahIndex::new(),
        );
        // Drain seg0 so there IS something reclaimable.
        {
            let alloc = engine.allocator_for(0);
            let mut a = alloc.lock();
            let o0 = a.allocate(4096).unwrap();
            let o1 = a.allocate(4096).unwrap();
            let _ = a.allocate(4096).unwrap();
            a.free(o0, 4096).unwrap();
            a.free(o1, 4096).unwrap();
        }

        engine.pin_segment_lifecycle();
        assert!(engine.is_segment_lifecycle_pinned());
        assert_eq!(
            engine.defrag_reclaim_fully_dead(),
            0,
            "reclaim must be a no-op while pinned even with a drained segment"
        );
        assert_eq!(
            engine.defrag_compact(4, 0.5),
            0,
            "compaction must be a no-op while pinned"
        );

        engine.unpin_segment_lifecycle();
        assert!(!engine.is_segment_lifecycle_pinned());
        assert_eq!(
            engine.defrag_reclaim_fully_dead(),
            1,
            "reclaim resumes after unpin"
        );
    }

