    // -- setMined correctness tests --

    #[test]
    fn set_mined_batch_applies_shared_params() {
        let engine = create_engine();

        // Create 3 txs.
        let mut keys = Vec::new();
        for n in 0..3u8 {
            let (_, req) = make_create_req(n + 100, 2);
            let key = req.tx_key();
            engine.create(&req).unwrap();
            keys.push(key);
        }

        let params = SetMinedSharedParams {
            block_id: 42,
            block_height: 800_000,
            subtree_idx: 7,
            current_block_height: 800_000,
            block_height_retention: 288,
            on_longest_chain: true,
            unset_mined: false,
        };

        let results = engine.set_mined_batch(&params, &keys);
        assert_eq!(results.len(), 3);
        for (i, r) in results.iter().enumerate() {
            let resp = r
                .as_ref()
                .unwrap_or_else(|e| panic!("item {i} failed: {e}"));
            assert!(
                resp.block_ids.contains(&42),
                "item {i} should have block_id 42"
            );
            // followup-2: `generation` was dropped from `SetMinedResponse`
            // entirely — setMined does zero device I/O, so there is no
            // generation to echo (it was already unused by the dispatch layer).
        }

        // Verify all three txs have the block entry (via the MinedIndex —
        // the authoritative source; the device fields stay untouched).
        for key in &keys {
            let (entries, _unmined) = engine.mined_block_entries(key).unwrap();
            assert_eq!(entries.len(), 1);
            assert_eq!({ entries[0].block_id }, 42);
        }
    }

